export async function reconnect(socket: Socket) {
  await socket.close(); // resolves on the close event
  return openSocket(socket.url);
}

files.src/session.test.ts:
it('reconnects after close', async () => {
  const s = await connect();
  const next = await reconnect(s);
  expect(next.state).toBe('open');
});

